import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"20、【观】 坤下巽上","description":"周易口诀义 - 20、【观】 坤下巽上","frontmatter":{"title":"20、【观】 坤下巽上","description":"周易口诀义 - 20、【观】 坤下巽上"},"headers":[],"relativePath":"zh/classics/koujueyi/022.md","filePath":"zh/classics/koujueyi/022.md"}'),r={name:"zh/classics/koujueyi/022.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_20、【观】-坤下巽上" tabindex="-1">20、【观】 坤下巽上 <a class="header-anchor" href="#_20、【观】-坤下巽上" aria-label="Permalink to “20、【观】 坤下巽上”">​</a></h1><p>彖曰：大观在上，顺而巽，中正以观天下。</p><p>「观盥而不荐，有孚颙若」，下观而化也。观天之神道而四时不忒，圣人以神道设教而天下服矣。</p><p>象曰：风行地上，观。先王以省方观民设教。</p><p>初六：童观，小人无咎，君子吝。</p><p>象曰：「初六童观」，「小人」道也。</p><p>六二：窥观，利女贞。</p><p>象曰：「窥观女贞」，亦可丑也。</p><p>六三：观我生，进退。</p><p>象曰：「观我生进退」，未失道也。</p><p>六四，观国之光，利用宾于王。</p><p>象曰：「观国之光」，尚宾也。</p><p>九五，观我生，君子无咎。</p><p>象曰：「观我生」，观民也。</p><p>上九，观其生，君子无咎。</p><p>象曰：「观其生」，志未平也。</p><p>解读</p><p>「观盥而不荐」者，观谓王者道德，民所观看也；盥谓瓶罍灌洗之器物也，荐谓笾豆陈荐之属也。今所观王者施瓶盥之礼，为民祈福，还威仪严敬否？故不观陈荐之物也。「有孚颙若」者，孚，信也，颙是严整之貌，谓君子行礼洁信，立诚端敬，颙然若鬼神在，则下观其德，民顺其化，故诗云「颙颙卬卬，如圭如璋」，君德之义也。象曰「风行地上，观」者，风如王者风教行于地上，人所观也。「先王省方，观民设教」者，先王以省视万方，观看民俗，施设教化，故郑众云：「从俗所为，顺民之教，故君子治人不求变俗」是也。如封太公于齐，五月报政，为简其君臣礼，从俗不同；伯禽于鲁，变其俗，易其礼，三年报政也。</p><p>「初六童观，小人无咎，君子吝」者，观之为体，下贱上贵也。最处于下，而不近朝廷之美，所观𥚹狭，如童稚之见，故云「童观」也。大观之时若如是，乃小人之见，才得无咎；君子居之，深可鄙吝也。</p><p>「六二𬮭观，利女贞」者，居内处中，所见非大，犹𬮭窃而观望，此乃利女之正，非丈夫之正，处大观之时，而为𬮭窃观看，诚可丑也。</p><p>「六三观我生，进退」者，生，犹道也。六三处下卦之上，是可进之时；居上卦之下，又是可退之地。处此之时，可以观风相几而不失其道也。</p><p>「六四观国之光，利用宾于王」者，处近君之尊，故可观国之光华矣；习国家之礼仪，故可利为王宾也。</p><p>「九五观我生，君子无咎」者，居得尊位，为观之主，四海之内，皆由我化。我化若善，天下习君子之风；我化不善，天下有小人之俗。故我观之道，有君子之风著，又何有咎也。</p><p>「上六观其生，君子无咎」者，观其生则是为人所观者也，最上处极，为天下所观于己之道，若能自戒慎，高尚其事，著君子之风，故得「无咎」。王传云：「独处异地，不易执持。」此明上九但卓立其身，异于尘俗，何咎之有？故论语云：「君子之过，如日月之食。过也，人皆见之；更也，人皆仰之。」</p>',24)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
